#!/usr/bin/env bash
# DLM v0.0057 -- the model learns from its own source.
#
# The model PERCEIVES its own call graph, INDUCES the governing composition law
# from examples it generated by walking its own edges (no human supplies the
# rule), RECURSIVELY feeds that law back through the kernel until it recovers
# reachability, EVALUATES its own deductive ability (recall of unobserved facts)
# against a one-composition control on a held-out edge split, and GROWS its
# hypothesis vocabulary so induction over a fixed alphabet does not plateau.
#
# Usage:
#   ./experiments/selflearn/selflearn.sh
#   ./experiments/selflearn/selflearn.sh --rounds 8 --max-body 2
#   OUTDIR=reports/selflearn/mine ./experiments/selflearn/selflearn.sh
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"
cd "$ROOT"
export PYTHONPATH="$ROOT${PYTHONPATH:+:$PYTHONPATH}"

STAMP="$(date +%Y%m%d-%H%M%S)"
OUTDIR="${OUTDIR:-reports/selflearn/${STAMP}}"
mkdir -p "$OUTDIR"

echo "== recursive self-supervised learning on the model's own source -> $OUTDIR"
python3 -u "$HERE/run.py" --json "$OUTDIR/result.json" "$@"
echo
echo "result: $OUTDIR/result.json"